// Commands with a (result ...)
inline bool hasResult(IrCmd cmd)
{
    return getCmdValueKind(cmd) != IrValueKind::None;
}

// Instructions that end a block (class :terminator)
inline bool isBlockTerminator(IrCmd cmd)
{
    switch (cmd)
    {
    case IrCmd::JUMP_EQ_POINTER:
    case IrCmd::JUMP:
    case IrCmd::JUMP_CMP_INT:
    case IrCmd::JUMP_IF_TRUTHY:
    case IrCmd::JUMP_IF_FALSY:
    case IrCmd::JUMP_EQ_TAG:
    case IrCmd::JUMP_CMP_NUM:
    case IrCmd::JUMP_CMP_FLOAT:
    case IrCmd::JUMP_FORN_LOOP_COND:
    case IrCmd::FALLBACK_FORGPREP:
    case IrCmd::JUMP_SLOT_MATCH:
    case IrCmd::RETURN:
    case IrCmd::FORGLOOP:
    case IrCmd::FORGLOOP_FALLBACK:
    case IrCmd::FORGPREP_XNEXT_FALLBACK:
    case IrCmd::JUMP_CMP_PROTOID:
        return true;
    default:
        return false;
    }
}

// Instructions that may branch to another block but otherwise continue (class :guard)
inline bool isNonTerminatingJump(IrCmd cmd)
{
    switch (cmd)
    {
    case IrCmd::CHECK_FASTCALL_RES:
    case IrCmd::CHECK_TAG:
    case IrCmd::CHECK_READONLY:
    case IrCmd::CHECK_NO_METATABLE:
    case IrCmd::CHECK_NODE_NO_NEXT:
    case IrCmd::CHECK_NODE_VALUE:
    case IrCmd::CHECK_OBJECT_CLASS:
    case IrCmd::CHECK_BUFFER_MUTABLE:
    case IrCmd::CHECK_USERDATA_TAG:
    case IrCmd::CHECK_CMP_INT:
    case IrCmd::CHECK_CMP_INT64:
    case IrCmd::CHECK_DIV_INT64:
    case IrCmd::CHECK_BUFFER_LEN:
    case IrCmd::CHECK_TRUTHY:
    case IrCmd::CHECK_SAFE_ENV:
    case IrCmd::CHECK_ARRAY_SIZE:
    case IrCmd::CHECK_CMP_NUM:
    case IrCmd::TRY_NUM_TO_INDEX:
    case IrCmd::TRY_CALL_FASTGETTM:
    case IrCmd::CHECK_SLOT_MATCH:
    case IrCmd::TRY_OBJECT_MEMBER_ADDR:
    case IrCmd::CHECK_CLASS_FIELDS_CONSTRUCTIBLE:
    case IrCmd::TRY_CLASS_MEMBER_ADDR:
    case IrCmd::TRY_OBJECT_NAMECALL_ADDR:
        return true;
    default:
        return false;
    }
}

// Instructions that are used for internal needs and are not a part of final lowering (class :pseudo)
inline bool isPseudo(IrCmd cmd)
{
    switch (cmd)
    {
    case IrCmd::NOP:
    case IrCmd::SUBSTITUTE:
    case IrCmd::MARK_USED:
    case IrCmd::MARK_DEAD:
        return true;
    default:
        return false;
    }
}

