// Instructions that can run user code and so invalidate the safe environment (heap-effects :invalidates-safe-env)
inline bool canInvalidateSafeEnv(IrCmd cmd)
{
    switch (cmd)
    {
    case IrCmd::CMP_ANY:
    case IrCmd::FALLBACK_GETGLOBAL:
    case IrCmd::FALLBACK_SETGLOBAL:
    case IrCmd::FALLBACK_GETTABLEKS:
    case IrCmd::FALLBACK_SETTABLEKS:
    case IrCmd::FALLBACK_NAMECALL:
    case IrCmd::FALLBACK_FORGPREP:
    case IrCmd::FALLBACK_NEWOBJECT:
    case IrCmd::FALLBACK_NEWCLASSMEMBER:
    case IrCmd::DO_ARITH:
    case IrCmd::DO_LEN:
    case IrCmd::GET_TABLE:
    case IrCmd::SET_TABLE:
    case IrCmd::CONCAT:
    case IrCmd::FORGLOOP_FALLBACK:
    case IrCmd::CALL:
        return true;
    default:
        return false;
    }
}

// Result-producing instructions that pass !hasSideEffects but are still unsafe to sink into ExitSync blocks (flag :deprecated/is-unsafe-to-sink)
inline bool isUnsafeToSink(IrCmd cmd)
{
    switch (cmd)
    {
    case IrCmd::LOAD_TAG:
    case IrCmd::LOAD_POINTER:
    case IrCmd::LOAD_DOUBLE:
    case IrCmd::LOAD_INT:
    case IrCmd::LOAD_INT64:
    case IrCmd::LOAD_FLOAT:
    case IrCmd::LOAD_TVALUE:
    case IrCmd::BUFFER_READI8:
    case IrCmd::BUFFER_READU8:
    case IrCmd::BUFFER_READI16:
    case IrCmd::BUFFER_READU16:
    case IrCmd::BUFFER_READI32:
    case IrCmd::BUFFER_READF32:
    case IrCmd::BUFFER_READF64:
    case IrCmd::BUFFER_READI64:
    case IrCmd::CMP_ANY:
    case IrCmd::GET_TYPEOF:
    case IrCmd::TABLE_LEN:
    case IrCmd::TABLE_SETNUM:
    case IrCmd::TRY_NUM_TO_INDEX:
    case IrCmd::TRY_CALL_FASTGETTM:
    case IrCmd::GET_UPVALUE:
    case IrCmd::TRY_OBJECT_MEMBER_ADDR:
    case IrCmd::TRY_CLASS_MEMBER_ADDR:
    case IrCmd::TRY_OBJECT_NAMECALL_ADDR:
        return true;
    default:
        return false;
    }
}

// Instructions whose result register may have garbage in its high bits (flag :dirty-high-bits)
inline bool producesDirtyHighRegisterBits(IrCmd cmd)
{
    switch (cmd)
    {
    case IrCmd::NUM_TO_UINT:
    case IrCmd::CMP_ANY:
    case IrCmd::INVOKE_FASTCALL:
        return true;
    default:
        return false;
    }
}

// Operand kinds of each command, from (operands ...): bits per IrOpKind, plus the IrValueKinds an Inst operand and the
// IrConstKinds a Constant operand may have
struct IrOperandSpec
{
    uint16_t opKinds = 0;
    uint16_t valueKinds = 0;
    uint8_t constKinds = 0;
}
;

struct IrCmdOperands
{
    uint8_t count = 0;
    IrOperandSpec ops[7];
    IrOperandSpec targetA64[7]; // extra kinds when compiling for A64 (target-specific)
    IrOperandSpec targetX64[7]; // extra kinds when compiling for X64 (target-specific)
    IrOperandSpec flagDebugLuauAbortingChecks[7]; // extra kinds with FFlag::DebugLuauAbortingChecks (flag-specific)
}
;

template<typename... Kinds>
constexpr uint16_t irOpKinds(Kinds... kinds)
{
    return uint16_t((0u | ... | (1u << unsigned(kinds))));
}

template<typename... Kinds>
constexpr uint16_t irValueKinds(Kinds... kinds)
{
    return uint16_t((0u | ... | (1u << unsigned(kinds))));
}

template<typename... Kinds>
constexpr uint8_t irConstKinds(Kinds... kinds)
{
    return uint8_t((0u | ... | (1u << unsigned(kinds))));
}

